{
  "restated_question": "On the evening of Oct 22, 2026 (Central time), USGS Northport (02465000), the National Water Model (reach 18229923), and NWS Oliver Lock & Dam (TODA1) reported very different flows for the Black Warrior River. Why do these three sources disagree, and what actually happened?",
  "hypotheses": [
    {
      "id": "H1",
      "claim": "A scheduled hydropower release from Holt Dam at 21:00 CDT (02:00 UTC) creates a sharp hydropeaking pulse that USGS Northport captures (peak 5,640 cfs at 21:00 CDT), but the NWM analysis/assimilation cycle did not include that hour on Oct 22, so NWM reverted to near-baseflow (170 cfs) and only peaked one hour later (5,516 cfs at 22:00 CDT)."
    },
    {
      "id": "H2",
      "claim": "NWS Oliver reports flow derived from tailwater stage at Oliver Lock & Dam, which reflects regulated releases through the dam, not the upstream pool inflow measured at Northport; the two gauges are at different hydraulic control points, so their flows differ systematically (NWS daily means ~300–400 cfs higher) even with zero rain and negligible pool-stage change."
    },
    {
      "id": "H3",
      "claim": "The daily hydropeaking pulse at Northport recurs at the same local hour (21:00 CDT) across all seven days with zero rainfall, confirming it is driven by scheduled dam operations at Holt, not natural runoff; this regulated pattern explains why NWM (which lacks dam-operation forcing) fails to match the magnitude and timing on days when its assimilation window misses the pulse hour."
    }
  ],
  "checks": [
    {
      "id": "C1",
      "hypothesis": "H1",
      "purpose": "Confirm the exact hour-by-hour values on Oct 22 CDT (02:00–06:00 UTC Oct 23) for USGS Northport, NWM, and NWS Oliver to quantify the NWM miss at the pulse hour and its +1 h lagged peak.",
      "how": "SELECT hr_utc, usgs_northport_cfs, usgs_northport_peak_cfs, nwm_cfs, nws_oliver_cfs FROM water.hourly_compare WHERE hr_utc BETWEEN '2026-10-23 02:00' AND '2026-10-23 06:00' ORDER BY hr_utc"
    },
    {
      "id": "C2",
      "hypothesis": "H2",
      "purpose": "Verify that USGS Oliver tailwater stage (02465005) and NWS Oliver tailwater stage (TODA1) are identical hour-by-hour (same sensor), while their derived flows differ, proving the disagreement is in stage-to-flow conversion, not stage measurement.",
      "how": "SELECT hr_utc, usgs_oliver_tailwater_ft, nws_oliver_tailwater_ft, nws_oliver_cfs, usgs_northport_cfs FROM water.hourly_compare WHERE hr_utc BETWEEN '2026-10-16 22:00' AND '2026-10-23 21:00' AND usgs_oliver_tailwater_ft IS NOT NULL AND nws_oliver_tailwater_ft IS NOT NULL ORDER BY hr_utc LIMIT 200"
    },
    {
      "id": "C3",
      "hypothesis": "H3",
      "purpose": "Test whether the USGS Northport peak occurs at the same local hour (21:00 CDT) on every day Oct 16–22 by extracting the CDT hour of the daily maximum 15-min peak; a consistent hour confirms scheduled hydropower releases.",
      "how": "SELECT DATE_SUB(hr_utc, 5) AS day_cdt, HOUR(DATE_SUB(hr_utc, 5)) AS peak_hour_cdt, MAX(usgs_northport_peak_cfs) AS max_peak_cfs FROM water.hourly_compare WHERE hr_utc BETWEEN '2026-10-16 22:00' AND '2026-10-23 21:00' GROUP BY day_cdt, peak_hour_cdt ORDER BY day_cdt, max_peak_cfs DESC LIMIT 200"
    },
    {
      "id": "C4",
      "hypothesis": "H2",
      "purpose": "Quantify the daily mean flow difference between USGS Northport and NWS Oliver over the full 6 full days (Oct 17–22) and compare to the daily pool-stage change at Northport; if stage change is negligible, the flow gap cannot be explained by storage and must be a rating-curve or hydraulic-control difference.",
      "how": "SELECT DATE_SUB(hr_utc, 5) AS day_cdt, AVG(usgs_northport_cfs) AS mean_usgs_cfs, AVG(nws_oliver_cfs) AS mean_nws_cfs, AVG(nws_oliver_cfs) - AVG(usgs_northport_cfs) AS diff_cfs, MAX(usgs_northport_stage_ft) - MIN(usgs_northport_stage_ft) AS stage_change_ft FROM water.hourly_compare WHERE hr_utc BETWEEN '2026-10-17 22:00' AND '2026-10-23 21:00' GROUP BY day_cdt ORDER BY day_cdt"
    }
  ]
}
